export interface HarnessConfig {
  /** The tools that the agent is allowed to use. */
  allowedTools?: string[] | Computed<string[]>;
  authorizerConfiguration?: Harness_AuthorizerConfiguration | Computed<Harness_AuthorizerConfiguration>;
  environmentArtifact?: Harness_EnvironmentArtifact | Computed<Harness_EnvironmentArtifact>;
  /** Environment variables to set in the harness runtime environment. */
  environmentVariables?: unknown | Computed<unknown>;
  /** The ARN of the IAM role that the harness assumes when running. */
  executionRoleArn: string | Computed<string>;
  /** The name of the harness. */
  harnessName: string | Computed<string>;
  /** The maximum number of iterations the agent loop can execute per invocation. */
  maxIterations?: number | Computed<number>;
  /** The maximum number of tokens the agent can generate per iteration. */
  maxTokens?: number | Computed<number>;
  /** Specifies the foundation model configuration (e.g., model ID or inference profile) that the Bedrock agent uses to process prompts and generate responses. (AI-inferred) */
  model: Harness_Model | Computed<Harness_Model>;
  /** The skills available to the agent. */
  skills?: Harness_Skills[] | Computed<Harness_Skills[]>;
  /** The system prompt that defines the agent's behavior. */
  systemPrompt?: Harness_SystemPrompt[] | Computed<Harness_SystemPrompt[]>;
  /** Tags to apply to the harness resource. */
  tags?: Harness_Tags[] | Computed<Harness_Tags[]>;
  /** The maximum duration in seconds for the agent loop execution per invocation. */
  timeoutSeconds?: number | Computed<number>;
  /** The tools available to the agent. */
  tools?: Harness_Tools[] | Computed<Harness_Tools[]>;
  truncation?: Harness_Truncation | Computed<Harness_Truncation>;
}

export interface HarnessAttrs {
  /** The tools that the agent is allowed to use. */
  allowedTools: string[];
  /** The Amazon Resource Name (ARN) of the harness. */
  arn: string;
  authorizerConfiguration: Harness_AuthorizerConfiguration;
  /** The timestamp when the harness was created. */
  createdAt: string;
  environment: Harness_Environment;
  environmentArtifact: Harness_EnvironmentArtifact;
  /** Environment variables to set in the harness runtime environment. */
  environmentVariables: unknown;
  /** The ARN of the IAM role that the harness assumes when running. */
  executionRoleArn: string;
  /** The unique identifier of the harness. */
  harnessId: string;
  /** The name of the harness. */
  harnessName: string;
  /** The maximum number of iterations the agent loop can execute per invocation. */
  maxIterations: number;
  /** The maximum number of tokens the agent can generate per iteration. */
  maxTokens: number;
  memory: Harness_Memory;
  /** Specifies the foundation model configuration (e.g., model ID or inference profile) that the Bedrock agent uses to process prompts and generate responses. (AI-inferred) */
  model: Harness_Model;
  /** The skills available to the agent. */
  skills: Harness_Skills[];
  status: string;
  /** The system prompt that defines the agent's behavior. */
  systemPrompt: Harness_SystemPrompt[];
  /** Tags to apply to the harness resource. */
  tags: Harness_Tags[];
  /** The maximum duration in seconds for the agent loop execution per invocation. */
  timeoutSeconds: number;
  /** The tools available to the agent. */
  tools: Harness_Tools[];
  truncation: Harness_Truncation;
  /** The timestamp when the harness was last updated. */
  updatedAt: string;
  /** The version of the harness. Incremented on every successful update. */
  version: string;
}

